// Demo: SSE/AVX Intrinsics — scalar vs vector throughput model
var n=1*1000,scalarPer=4,vecWidth=8,vecPer=6;
var scalarCycles=n*scalarPer,vecCycles=(n/vecWidth)*vecPer;
console.log('technique: SSE/AVX Intrinsics');console.log('elements: '+n);
console.log('scalar cycles: '+scalarCycles+', vector cycles: '+Math.round(vecCycles));
console.log('modeled speedup: '+(scalarCycles/vecCycles).toFixed(1)+'x');

