// Demo: Auto-Vectorization Pragmas — alignment effect on throughput
function tput(size,aligned){var base=size/8;return aligned?base:base*1.6;}
var n=30*64;
console.log('technique: Auto-Vectorization Pragmas');console.log('aligned  : '+tput(n,true).toFixed(0)+' cycles');
console.log('unaligned: '+tput(n,false).toFixed(0)+' cycles');
console.log('align data to 32/64 bytes to avoid the penalty');

